package com.spaceagent.platform.contracts;
import com.fasterxml.jackson.databind.DeserializationFeature;import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.runtime.domain.multiagent.GraphV2Contract;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PlatformGraphV2ContractCompatibilityTest {private final ObjectMapper json=new ObjectMapper().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);private static final Path F=Path.of("../../contracts/multi-agent/v2/fixtures");@Test void parsesSharedV2CursorAndStableCommand(){try{var r=json.readValue(Files.readString(F.resolve("graph-request.json")),RequestFixture.class);var o=json.readValue(Files.readString(F.resolve("graph-result.json")),ResultFixture.class);var request=new GraphV2Contract.Request(r.contractVersion,r.requestId,r.graphSessionId,r.agentRunId,r.tenantId,r.ownerUserId,r.bundleHash,new GraphV2Contract.Cursor(r.cursor.sequence,r.cursor.completedCommandIds,r.cursor.pendingCommandId),new GraphV2Contract.Limits(r.limits.maxDepth,r.limits.maxAgents,r.limits.remainingTokenBudget));var result=new GraphV2Contract.Result(o.contractVersion,o.requestId,o.graphSessionId,o.bundleHash,new GraphV2Contract.Cursor(o.nextCursor.sequence,o.nextCursor.completedCommandIds,o.nextCursor.pendingCommandId),new GraphV2Contract.Command(o.command.commandId,GraphV2Contract.Kind.valueOf(o.command.kind),o.command.inputHash,o.command.payload),o.ephemeral);assertEquals(request.bundleHash(),result.bundleHash());assertEquals("cmd-3",result.command().commandId());}catch(Exception e){throw new AssertionError(e);}}record RequestFixture(String contractVersion,String requestId,String graphSessionId,String agentRunId,String tenantId,String ownerUserId,String bundleHash,Cursor cursor,Limits limits){}record ResultFixture(String contractVersion,String requestId,String graphSessionId,String bundleHash,Cursor nextCursor,Command command,boolean ephemeral){}record Cursor(int sequence,List<String> completedCommandIds,String pendingCommandId){}record Limits(int maxDepth,int maxAgents,int remainingTokenBudget){}record Command(String commandId,String kind,String inputHash,Map<String,Object> payload){}}
